  const avisarIngesta = rIngesta && typeof rIngesta === 'object' ? rIngesta.avisarRecepcion : '';
  const avisarCfg = a && a.avisarRecepcion !== undefined ? a.avisarRecepcion : cfg.atencionAvisarRecepcion;
  const avisar = ['operador', 'bloqueado'].indexOf(avisarIngesta || avisarCfg) >= 0 ? (avisarIngesta || avisarCfg) : '';
  return {
    estado: estado,
    avisar: avisar,
    mensajeFijo: String((a && a.mensajeFijo) || cfg.atencionMensajeFijo || '').trim(),
    respuestas: Number(a && a.respuestasEnVentana !== undefined ? a.respuestasEnVentana : cfg.atencionRespuestas) || 0,
    venceEn: String((a && a.ventanaVenceEn) || cfg.atencionVenceEn || ''),
  };
}

// =============================================================================
// MENSAJES (prefijo `cm`): los constructores de lo que sale por WhatsApp, en JavaScript plano
// =============================================================================
// Se pega DELANTE del código de un nodo Code (el construir.mjs de esta carpeta lo hace con la marca
// `@@comun+mensajes:…` o `@@solo+mensajes:…`): el nodo Code de n8n no tiene módulos. Es AUTOSUFICIENTE: no
// usa ninguna función `cn*` ni ningún nodo, no lee la configuración y no llama a la red, así que sirve igual en
// cualquier flujo. Sin `require`, `URL`, `Buffer` ni `crypto` (el Code de n8n no los tiene).
//
// Sacado de `agenda-minima/src/nodos/armar-mensajes.js`, que sigue con sus copias. Los límites son los de la
// Cloud API de Meta: texto 4096, cuerpo interactivo 1024, botón 20, tres botones, fila de lista 24 y su
// descripción 72, diez filas, id de botón o de fila 200.
//
// El PAYLOAD que sale de aquí lleva `to: ''` a propósito: el destinatario lo pone un solo nodo, el último
// (en modo prueba, TODO va al teléfono de prueba), y no cada constructor.
//
// Un ITEM de salida es `{ para, payload, texto, respaldo, ...extra }`:
//   para     quién lo recibe, en palabras del flujo («cliente», «recepcion»…);
//   payload  el cuerpo de la Cloud API;
//   texto    lo que se reporta a la consola (nunca el contenido de un medio);
//   respaldo texto plano que se manda SI Meta rechaza el interactivo (nunca se pierde un mensaje).

function cmRecorte(t, max) {
  const s = String(t === undefined || t === null ? '' : t);
  if (s.length <= max) return s;
  let corte = s.slice(0, max - 1);
  // Nunca se parte un emoji (un par sustituto) por la mitad: Meta rechaza el mensaje con un medio carácter.
  if (/[\uD800-\uDBFF]$/.test(corte)) corte = corte.slice(0, -1);
  return corte.trimEnd() + '…';
}
function cmBase(tipo) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', to: '', type: tipo };
}
function cmTexto(cuerpo) {
  return Object.assign(cmBase('text'), { text: { preview_url: true, body: cmRecorte(cuerpo, 4000) } });
}
function cmBotones(cuerpo, botones) {
  return Object.assign(cmBase('interactive'), { interactive: {
    type: 'button', body: { text: cmRecorte(cuerpo, 1024) },
    action: { buttons: (botones || []).slice(0, 3).map((b) => ({ type: 'reply', reply: { id: cmRecorte(b.id, 200), title: cmRecorte(b.title, 20) } })) },
  } });
}
function cmLista(cuerpo, boton, titulo, filas) {
  return Object.assign(cmBase('interactive'), { interactive: {
    type: 'list', body: { text: cmRecorte(cuerpo, 1024) },
    action: { button: cmRecorte(boton, 20), sections: [{ title: cmRecorte(titulo, 24), rows: (filas || []).slice(0, 10).map((f) => ({
      id: cmRecorte(f.id, 200), title: cmRecorte(f.title, 24), description: cmRecorte(f.description || '', 72) })) }] },
  } });
}
function cmEnlace(cuerpo, texto, url) {
  // Un botón con enlace solo lleva `https://`: cualquier otro esquema (`javascript:`, `http:`…) no sale como botón,
  // sale el texto sin el enlace.
  if (!/^https:\/\/[^\s]+$/i.test(String(url))) return cmTexto(cuerpo);
  return Object.assign(cmBase('interactive'), { interactive: {
    type: 'cta_url', body: { text: cmRecorte(cuerpo, 1024) },
    action: { name: 'cta_url', parameters: { display_text: cmRecorte(texto, 20), url: String(url) } },
  } });
}
// El enlace que abre un chat de WhatsApp con un número (solo dígitos) y un saludo ya escrito.
function cmUrlWa(numero, saludo) {
  return 'https://wa.me/' + String(numero).replace(/\D/g, '') + '?text=' + encodeURIComponent(cmRecorte(saludo || '', 300));
}
function cmMensaje(para, payload, texto, respaldo, extra) {
  return Object.assign({ para: para, payload: payload, texto: texto, respaldo: respaldo || texto }, extra || {});
}
// Un texto que nombra «el botón» cuando no hay botón queda mal: se le quitan esas frases.
function cmSinMencionDelBoton(cuerpo, porDefecto) {
  const s = String(cuerpo || '').replace(/\s*T[oó]ca(le)? el bot[oó]n[^.!?]*[.!?]?/gi, '')
    .replace(/\s*tocando el bot[oó]n/gi, '').replace(/\s+([.,])/g, '$1').trim();
  return s || String(porDefecto || '');
}
// PASAR CON UNA PERSONA: el mensaje con el botón que abre su chat, o solo texto si no hay a quién mandarlo.
//   op = { numero, desde, cuerpo, botonTexto, saludo, para?, evento?, textoDelRespaldo?, sinNumero? }
// Hay botón solo si `numero` existe y NO es el de quien escribe (`desde`): un botón a su propio chat no sirve.
// Devuelve el item, con `tipoReporte` ('interactive' o 'text') y `conBoton`.
function cmContactoConBoton(op) {
  const numero = String(op.numero || '').replace(/\D/g, '');
  const desde = String(op.desde || '').replace(/\D/g, '');
  const para = op.para || 'cliente';
  if (numero && numero !== desde) {
    const url = cmUrlWa(numero, op.saludo || '');
    const pie = '\n\n' + cmRecorte(op.textoDelRespaldo || 'Escríbele aquí:', 100) + ' ' + url;
    // El respaldo es TEXTO (tope 4000): se recorta el cuerpo, nunca el enlace del final.
    return cmMensaje(para, cmEnlace(op.cuerpo, op.botonTexto || 'Escribir', url), op.cuerpo,
      cmRecorte(op.cuerpo, 4000 - pie.length) + pie,
      { tipoReporte: 'interactive', evento: op.evento, conBoton: true });
  }
  const sinBoton = cmSinMencionDelBoton(op.cuerpo, op.sinNumero || 'Eso lo coordina una persona del equipo.');
  return cmMensaje(para, cmTexto(sinBoton), sinBoton, sinBoton, { tipoReporte: 'text', evento: op.evento, conBoton: false });
}

// =============================================================================
// FILTRO DE LA REDACCIÓN DEL MODELO (prefijo `cm`): lo que el modelo escribe NO sale sin pasar por aquí
// =============================================================================
// Se pega DELANTE del código de un nodo Code (marca `@@comun+filtro:…` o `@@solo+filtro:…`). Autosuficiente:
// no usa funciones `cn*` ni lee nada. Principio del flujo «sin agente»: el código calcula y el modelo conversa;
// cuando el modelo redacta, el código VERIFICA lo redactado y, si algo falla, lo descarta y usa un texto fijo.
// Ninguna regla es una instrucción al modelo: una instrucción se ignora bajo insistencia (CLAUDE.md).
//
// Sacado de `agenda-minima/src/nodos/armar-mensajes.js` (que sigue con sus copias), SIN lo que es de un negocio:
// ni lo clínico ni las horas de una agenda ni nombres de personas. Eso entra por `opciones`.
//
//   cmMotivoDeRechazo(texto, opciones) -> '' si el texto puede salir, o el MOTIVO del rechazo
//   cmRedaccionValida(texto, opciones) -> true/false
//   cmPulirRedaccion(texto, opciones)  -> el texto sin saludo repetido, sin muletillas y con el nombre del negocio bien escrito
//
// opciones de `cmMotivoDeRechazo` (todas opcionales):
//   maximo            largo máximo (900)
//   permitirMontos    false por defecto: un MONTO nunca sale de la redacción, lo dice el código con su cifra
//   enlacesPermitidos los enlaces COMPLETOS del negocio; por defecto NINGÚN enlace sale (null apaga la revisión)
//   quienPromete      sujetos (ya normalizados) cuyo «<sujeto> te…» es una promesa: ['recepcion', 'el doctor']
//   prohibidos        regex extra, probadas contra el texto NORMALIZADO (minúsculas y sin tildes)
//   textoDelCliente   lo que preguntó el cliente: a una pregunta de IDENTIDAD no se contesta empezando con «Sí»
//   sinImagenes       true: el flujo NO envía imágenes; «te muestro / envío fotos, capturas, la portada…» es una promesa sin respaldo
//                     y se rechaza con el motivo `promete_imagenes`. Apagado por defecto (hay flujos que sí envían imágenes)
//   extra             funciones (texto, normalizado) => motivo ('' si pasa): las reglas propias del flujo (horas, etc.)
// Las promesas sin respaldo, afirmar un hecho que solo el código puede afirmar (quedó agendado, pago acreditado…),
// negar ser una IA y los huecos de plantilla se revisan SIEMPRE, y no se pueden apagar.

function cmNorm(t) {
  // NFKC junta las formas de ancho completo («ｑｕｅｄó» → «quedó»); se quitan los caracteres invisibles (U+200B a U+200D,
  // U+2060, U+FEFF) y el guion blando, que partían una palabra sin que se viera («agen​dé»).
  return String(t === undefined || t === null ? '' : t).normalize('NFKC').replace(/[​-‍⁠﻿­]/g, '').replace(/[。｡]/g, '.')
    .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}
// El texto SIN los guiones, puntos y asteriscos que parten una palabra para esconderla («agen-dada», «a.gen.dé»).
function cmJunto(n) {
  return n.replace(/(\p{L})[-.·_*]+(?=\p{L})/gu, '$1');
}
// Letras sueltas separadas por espacios, guiones o puntos («p a g o», «p. a. g. o», «p-a-g-o»): se juntan las rachas de 3 o más
// letras sueltas. Se usa JUNTO con el texto sin tocar (nunca en lugar de él), así que no rompe montos ni teléfonos (no son letras).
function cmJuntoLetras(n) {
  return cmJunto(n.replace(/(?<![\p{L}\p{N}])\p{L}(?:[\s\-.·_*]+\p{L}(?![\p{L}\p{N}])){2,}/gu, (m) => m.replace(/[\s\-.·_*]+/g, '')));
}
// Homoglifos: una palabra que mezcla letras latinas con otro alfabeto (cirílico, griego…) esconde otra palabra («pаgo» con una
// «а» cirílica). El español no los usa; se rechaza el texto entero. No toca emojis, signos ni números.
function cmAlfabetoMixto(texto) {
  const palabras = String(texto || '').normalize('NFKC').match(/[\p{L}\p{M}]+/gu) || [];
  return palabras.some((w) => /\p{Script=Latin}/u.test(w) && /[^\p{Script=Latin}\p{M}\p{Script=Common}\p{Script=Inherited}]/u.test(w));
}
// «Política: el asistente solo ofrece lo que el flujo cumple»: ninguna promesa sin un mecanismo detrás.
const CM_PROMESAS = /lo consulto|lo consultar[eé]|consultar[eé]|\b(te|le) avis(o|ar[eé]|amos)\b|\b(te|le) llam(amos|ar[eé]|aremos)\b|te vamos a (llamar|avisar|escribir|contactar)|te van a (llamar|contactar|escribir|avisar)|te escribir[aá]n|te escribiremos|\b(te|le) contactar[eé]|nos comunicaremos|\b(te|le) confirm(o|ar[eé]) (luego|despues|mas tarde|manana)|te confirmar[eé]/;
// Lo que SOLO el código puede afirmar. Por defecto se rechaza todo lo que SUENA a confirmación: un falso rechazo
// cae en el texto fijo del código (barato); un falso «quedó agendada» es una cita que no existe (CLAUDE.md).
//   - participios de lo que el código hace o confirma: agendada, reservado, registrado, confirmada, anotado,
//     reprogramada, cancelada, acreditado, aprobado, verificado, pagado, recibido (de un pago)…
//   - primera persona: «agendé», «reservé», «registré», «confirmé», «anoté», «reprogramé», «he reservado»…
//   - el pago: «recibimos tu pago», «pago recibido/acreditado/aprobado», «tu pago fue…»
//   - marcas de visto bueno que pone el código: ✅ ✔ ☑
// Y negar ser una IA (prohibición 4: NUNCA): «no soy un bot / una máquina / un asistente», «soy una persona»,
// «hablas con una persona», «persona real», «de carne y hueso».
// Medios y sustantivos del pago. Medios que existen en Bolivia: QR simple, transferencia, Tigo Money, tarjeta, efectivo y depósito.
// (Yape, Nequi, PIX… no existen aquí y no se listan.)
// Formas EXPLÍCITAS (nunca `pag\w*`: «página» no es un pago) y sin `cancel*` (cancelar una suscripción no es pagar; «cancelaste/cancelamos/cancelaron» tienen su regla).
