  '\\bsaldo (?:en |a )?cero\\b',
  '(?=\\b' + CM_VERBO_RECEPCION + '\\b)' + CM_NO_PREGUNTA + '\\b' + CM_VERBO_RECEPCION + '\\b[^.!?]{0,30}(?:\\$|\\bdolares?\\b|\\busdt?\\b)',
