  '\\b(?:todo|esta|estan) (?:en orden|ok|bien|correcto|perfecto)\\b[^.!?]{0,6}\\bcon (?:tu|tus|el|los|la|las|su|sus) (?:\\w+ )?(?:' + CM_PAGO_HECHO + '|qr)\\b',
