  if (rrPrecio(cat, 'closer') !== null) partes.push('el Prompt Closer ' + rrMontoBs(rrPrecio(cat, 'closer')));
  if (rrPrecio(cat, 'videos') !== null) partes.push('los videos con IA ' + rrMontoBs(rrPrecio(cat, 'videos')));
