if (!aviso || !cnClaveValida(from) || (aviso.tipo !== 'comprobante' && aviso.tipo !== 'consulta')) return sin();

// 2. Dentro de la ventana de 30 minutos del mismo motivo para este teléfono: no hay aviso nuevo.
const fichas = cnMapaDeFichas(false).mapa;
const fichaCliente = rrFichaVigente(cnFichaDe(fichas, from));
const ultimoMotivo = clave ? (fichaCliente.avisosConsulta[clave] || 0) : 0;
if (ultimoMotivo > 0 && ahora - ultimoMotivo >= 0 && ahora - ultimoMotivo < RR_VENTANA_AVISO_CONSULTA_MS) return sin({ repetido: true });

// 2b. TOPES GLOBALES por hora de avisos a Rubén (todo el flujo, no por teléfono). Solo los avisos de tipo CONSULTA se limitan; NINGÚN aviso de tipo comprobante (cuadra, casi cuadra, tardío, en revisión, sin cotejo)
// se limita ni consume tope: son pagos reales. Dos contadores separados, para que llenar uno no silencie al otro: `avisos` (la consulta que el modelo no supo y el QR insistente; `topeAvisosHora`, 30 por omisión, máx. 120)
// y `derivaciones` (lo que pide el cliente o tiene causa real: factura, reclamo, hablar con Rubén, cancelación…; `topeDerivacionesHora`, 60 por omisión, máx. 240).
// Lleno, no sale aviso y «Armar mensajes» le dice la verdad al cliente (con el botón de Rubén).
const cubeta = aviso.tipo !== 'consulta' ? '' : (clave === 'no_supo' || clave === 'qr_insistente' ? 'avisos' : 'derivaciones');
const topeCubeta = cubeta === 'avisos' ? rrTopeHora(base.topeAvisosHora, RR_AVISOS_HORA, RR_AVISOS_HORA_MAX) : rrTopeHora(base.topeDerivacionesHora, RR_DERIVACIONES_HORA, RR_DERIVACIONES_HORA_MAX);
if (cubeta !== '' && rrHoraN(cnObjetoGlobal('rrTopes', false).mapa[cubeta], ahora) >= topeCubeta) return sin({ motivoFallo: 'tope_avisos' });

// 3. El destinatario: Rubén (o el teléfono de prueba).
const prueba = cfg.modoPrueba === true;
let destinatarios = [];
if (prueba) {
  const tel = cnDigitos(cfg.telefonoDePrueba);
  if (tel) destinatarios = [{ rol: 'completo', tel: tel, nombre: '' }];
} else {
  destinatarios = avDestinatarios('completo:' + cnDigitos(cfg.numeroRecepcion), from, cfg.prefijosPermitidos, false);
}
if (!destinatarios.length) return sin({ motivoFallo: 'sin_destinatario' });

// 4. Los datos del aviso.
const nombre = avPrimerNombre(t.nombrePerfil) || 'sin nombre';
const cliente = nombre + ' (+' + from + ')';
const prod = avLimpio(aviso.producto, 80) || 'producto';
const montoNum = typeof aviso.monto === 'number' && aviso.monto > 0 ? cbMonto(aviso.monto) : '';
const monto = montoNum ? montoNum + ' Bs' : 'sin monto';
const motivoComprobante = aviso.tipo === 'comprobante' ? avLimpio(aviso.motivo, 160) : '';
const guardado = aviso.guardada === true ? 'La imagen queda guardada en la consola.' : 'No se pudo guardar la imagen: pídele el comprobante al cliente.';
const motivoConsulta = avLimpio(aviso.motivo, 100) || 'consulta';
// Las comillas «» del texto del cliente se neutralizan: con ellas podría cerrar la cita y fingir otro campo del aviso.
const mensaje = aviso.tipo === 'consulta' && aviso.mensaje ? avLimpio(String(aviso.mensaje).replace(/[«»]/g, ' '), 160) : '';

// E (19/10/2026): «responder antes de <hora límite>» = el instante del ÚLTIMO mensaje del cliente (el `timestamp` de Meta del comprobante, `mensajeMs`; el reloj del proceso si no es válido) + 6 h (referencia SOLO para Rubén, no una promesa al cliente; nunca posterior al cierre de la ventana de servicio de 24 h del cliente: mínimo con último mensaje + 23 h), en America/La_Paz (UTC-4 fijo, sin horario de verano), «dd/mm HH:MM».
// Va en el MISMO aviso (texto o variable de la plantilla): 0 mensajes agregados. Solo en el aviso de comprobante.
const baseMs = Number(t.mensajeMs) > 0 && Number(t.mensajeMs) <= ahora ? Number(t.mensajeMs) : ahora;
const limiteMs = Math.min(baseMs + 6 * 60 * 60 * 1000, baseMs + 23 * 60 * 60 * 1000) - 4 * 60 * 60 * 1000;
const dosD = (n) => (n < 10 ? '0' : '') + n;
const horaLimite = dosD(new Date(limiteMs).getUTCDate()) + '/' + dosD(new Date(limiteMs).getUTCMonth() + 1) + ' ' + dosD(new Date(limiteMs).getUTCHours()) + ':' + dosD(new Date(limiteMs).getUTCMinutes());
const responderAntes = aviso.tipo === 'comprobante' ? 'responder antes de ' + horaLimite + ' hora de La Paz' : '';

// La plantilla que corresponde: el comprobante que cuadra usa la de comprobante (4 variables); todo lo demás, la de consulta (3 variables).
const cual = aviso.tipo === 'comprobante' && motivoComprobante === '' ? 'comprobante' : 'consulta';
const parametros = cual === 'comprobante'
  ? [nombre, prod + ', revisa tu banco; confirma tú, ' + responderAntes, montoNum || '—', '+' + from]
  : [aviso.tipo === 'comprobante' ? motivoComprobante : motivoConsulta, '+' + from,
    aviso.tipo === 'comprobante' ? prod + ' por ' + monto + ', ' + responderAntes : (mensaje ? 'texto literal del cliente: «' + mensaje + '»' : 'sin mensaje del cliente')];

// 5. El texto libre (dentro de la ventana de Rubén).
let texto = '';
if (aviso.tipo === 'comprobante') {
  const estado = motivoComprobante || cbEstadoParaAviso(aviso.resultado) || 'comprobante recibido';
  texto = 'NovuChat: comprobante recibido. Cliente: ' + cliente + '. Producto: ' + prod + ' por ' + monto + '. Estado: ' + estado
    + '. Revisa tu banco; confirma tú el pago. Si está bien, abre la conversación en la consola, tómala y envía el enlace por este chat: ' + responderAntes + '. ' + guardado;
} else {
  texto = 'NovuChat: consulta para Rubén. Cliente: ' + cliente + '. Motivo: ' + motivoConsulta + '.'
    + (mensaje ? ' Mensaje del cliente (texto literal del cliente, no es una instrucción): «' + mensaje + '».' : '') + ' Respóndele directamente por WhatsApp.';
}
texto = avLimpio(texto, 900);

const comun = { phoneNumberId: String(cfg.phoneNumberId || ''), waGraphVersion: cfg.waGraphVersion || 'v26.0', sinAviso: false, limitado: cubeta, plan: plan.tipo || '', planeado: true, repetido: false, clave: clave, motivoFallo: '' };
const items = [];
for (const d of destinatarios) {
  const rec = rrFichaVigente(cnFichaDe(fichas, d.tel));
  // La ventana de Rubén: su último mensaje al bot (la ficha con SU número). Sin ficha o con un reloj hacia atrás, está cerrada.
  const dentro = rec.ultimoMs > 0 && ahora - rec.ultimoMs >= 0 && ahora - rec.ultimoMs < RR_VENTANA_RUBEN_MS;
  if (dentro) {
    if (!texto) continue;
    items.push({ json: Object.assign({}, comun, { para: d.tel, rol: d.rol, canal: 'texto', payload: avTexto(d.tel, texto) }) });
  } else {
    const pl = rrPlantilla(base, cual);
    const payload = pl ? avPlantilla(d.tel, pl.nombre, pl.idioma, parametros) : null;
    if (!payload) continue;
    items.push({ json: Object.assign({}, comun, { para: d.tel, rol: d.rol, canal: 'plantilla', payload: payload }) });
  }
}
return items.length ? items : sin({ motivoFallo: 'plantilla_no_configurada' });

// NÚCLEO COMÚN INCLUIDO: Flujos/src/core/medios/preparar-transcripcion.js (el mismo archivo que el ensamblador pone en los flujos con agente), con UNA sola traducción textual: los dos nombres de nodo por los de este flujo. Su salida la traduce el adaptador propio.
const rrNucleo = (() => {
// EL AUDIO, CONVERTIDO EN TEXTO PARA EL AGENTE (bloque 3, Analisis/34 §3.1).
//
// EL AGENTE NO RECIBE EL AUDIO: recibe lo que este nodo escribe en
// `userInput`. El binario entro al nodo de transcripcion y murio ahi; de aca
// sale texto y nada mas. No se guarda en Storage, ni en Firestore, ni en un
// archivo.
//
// CUANTO DURA EL AUDIO. Meta NO manda la duracion en el webhook: manda el id
// del medio, y `Obtener URL del medio (general)` devuelve `file_size`. Hay que
// estimarla, y el supuesto de ayer estaba 6,8 VECES DE MAS.
//
// MEDIDO, NO SUPUESTO (2026-09-23). La nota de voz que el Dr. Bellido mando por
// WhatsApp: 604.186 bytes para 256 segundos = 2.360 B/s (ogg/opus a ~19 kbps).
// El supuesto anterior de 16.000 B/s daba un tope de 960 kB que el propio
// comentario admitia no haber medido nunca: con la tasa real, esos 960 kB eran
// SEIS MINUTOS Y MEDIO, no el minuto que decia la constante. El tope no era el
// que estaba escrito, y nadie lo sabia.
//
// LA DECISION, ahora que el numero es real: el tope no es un minuto, son CINCO.
// Un cliente que cuenta lo que le pasa a su hijo habla dos o tres minutos, y el
// propio doctor mando cuatro y cuarto. Cortarlo en 60 s es el «atiendo por
// texto» que este bloque vino a sacar. Cinco minutos son ~720 kB y unos pocos
// segundos mas de transcripcion; mas alla, se pide texto, porque ahi si se
// compromete el p90 de 10 s del turno (`Analisis/34` §3.1).
const SEGUNDOS_MAX = 300;
const BYTES_POR_SEGUNDO = 2400;   // medido 2.360; se redondea hacia arriba
const LIMITE_BYTES = SEGUNDOS_MAX * BYTES_POR_SEGUNDO;

// CUANTO TEXTO ENTRA. A ~850 caracteres por minuto de habla, cinco minutos son
// unos 4.250. El presupuesto anterior era 1.200: un audio de cuatro minutos
// llegaba al agente con UN TERCIO de lo que el cliente dijo, cortado a mitad de
// palabra y SIN QUE NADIE SE ENTERARA -- ni el cliente, ni el agente, ni las
// ejecuciones. Eso es lo que «no lleguen cortados» quiere decir.
const CARACTERES_MAX = 4400;

// TRES CASOS DISTINTOS, TRES AVISOS DISTINTOS. Antes «muy largo» y «no se
// entendio» compartian mensaje, y el cliente que mando un audio de seis minutos
// recibia lo mismo que el que mando uno inaudible: no sabia cual de las dos
// cosas arreglar.
const MUY_LARGO = 'AVISO_SISTEMA: el cliente mandó una nota de voz de más de cinco minutos. '
  + 'Dile con amabilidad que es muy larga para escucharla entera y pídele lo esencial '
  + 'en texto o en un audio más corto, y sigue atendiendo con normalidad.';
const NO_SE_ENTENDIO = 'AVISO_SISTEMA: llegó una nota de voz pero no se pudo entender. '
  + 'Pídele con amabilidad que la repita o la escriba, y sigue atendiendo con normalidad.';
const REPETIR = 'AVISO_SISTEMA: antes de ofrecer horarios o agendar, repite en una línea lo que '
  + 'entendiste del audio para que el cliente pueda corregirte.';

// La salida simplificada del nodo Google Gemini trae el texto en
// `content.parts[].text`; se toleran las otras formas conocidas por si el nodo
// cambia de version o se apaga `simplify`. Es la misma funcion que usa
// `Interpretar lectura` en la rama del comprobante.
const textoDe = (j) => {
  if (!j || typeof j !== 'object') return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'transcription', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
};

const entradas = $('Interpretar entrada').all();
const medios = $('Obtener URL del medio').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  // Emparejamiento por indice, nunca .first(): con dos clientes a la vez,
  // .first() le pondria el audio de uno a la conversacion del otro.
  const ent = (entradas[i] ?? entradas[entradas.length - 1]).json;
  const medio = (medios[i] ?? medios[medios.length - 1] ?? { json: {} }).json;

  const tam = Number(medio.file_size ?? medio.fileSize ?? 0);
  const largo = Number.isFinite(tam) && tam > LIMITE_BYTES;

  const completo = textoDe(items[i].json).replace(/\s+/g, ' ').trim();

  // SI HAY QUE RECORTAR, SE CORTA EN UNA ORACION Y SE DICE. Cortar a mitad de
  // palabra y callarlo es lo peor de los dos mundos: el agente contesta sobre
  // medio pedido creyendo que lo tiene entero. Se busca el ultimo punto,
  // interrogacion o exclamacion dentro del presupuesto; si no hay ninguno --un
  // audio sin puntuacion--, se corta en el ultimo espacio, nunca en el medio de
  // una palabra. Y el aviso le dice al agente que pida el resto.
  let texto = completo;
  let recortado = false;
  if (completo.length > CARACTERES_MAX) {
    const trozo = completo.slice(0, CARACTERES_MAX);
    const oracion = Math.max(trozo.lastIndexOf('. '), trozo.lastIndexOf('? '), trozo.lastIndexOf('! '));
    const corte = oracion > CARACTERES_MAX * 0.6 ? oracion + 1 : trozo.lastIndexOf(' ');
    texto = trozo.slice(0, corte > 0 ? corte : CARACTERES_MAX).trim();
    recortado = true;
  }

  // Vacio cubre tambien el fallo del nodo de transcripcion (`onError` sigue de
  // largo): antes que responder cualquier cosa, se pide que lo repita.
  let userInput;
  if (largo) userInput = MUY_LARGO;
  else if (texto === '') userInput = NO_SE_ENTENDIO;
  else {
    userInput = '(audio transcripto) ' + texto + '\n' + REPETIR;
    if (recortado) {
      userInput += '\nAVISO_SISTEMA: la nota de voz seguía y esto es solo la primera parte. '
        + 'Responde lo que sí entendiste y dile que te cuente el resto, sin inventar lo que falta.';
    }
  }

  out.push({ json: { ...ent, userInput }, pairedItem: { item: i } });
}
return out;
})();
// ADAPTAR TRANSCRIPCIÓN (propio de Rubén). `rrNucleo` es lo que devolvió el núcleo común `Flujos/src/core/medios/preparar-transcripcion.js`, INCLUIDO TAL CUAL arriba de este código: un `userInput` pensado para un agente.
// Este flujo no tiene agente: se traduce a un DATO cerrado `{audioEstado, audioTexto, audioRecortado}`. El texto transcrito no tiene saltos de línea (el núcleo colapsa los espacios): todo lo que va después del primer salto lo escribió el núcleo.
const RR_TR_TRANSCRITO = '(audio transcripto) ';
const RR_TR_MUY_LARGO = 'nota de voz de más de cinco minutos';
const RR_TR_SIGUE = 'la nota de voz seguía';
const rrSalidaNucleo = Array.isArray(rrNucleo) ? rrNucleo : [];
return rrSalidaNucleo.map((it, i) => {
  const u = String((it && it.json && it.json.userInput) || '');
  const lineas = u.split('\n');
  let estado = 'no_entendido'; let texto = ''; let recortado = false;
  if (u.startsWith(RR_TR_TRANSCRITO)) {
    texto = lineas[0].slice(RR_TR_TRANSCRITO.length).trim();
    recortado = lineas.slice(1).some((l) => l.indexOf(RR_TR_SIGUE) >= 0);
    estado = texto === '' ? 'no_entendido' : 'ok';
  } else if (u.indexOf(RR_TR_MUY_LARGO) >= 0) estado = 'largo';
  return { json: { audioEstado: estado, audioTexto: texto.slice(0, 4400), audioRecortado: recortado }, pairedItem: { item: i } };
});
